import pyomo.environ as pyo

DATA = {
    "attractions": [1, 2, 3, 4],
    "cost": {1: 100, 2: 200, 3: 300, 4: 400},
    "upper_bound": {1: 20, 2: 15, 3: 25, 4: 30},
    "x1_x2_limit": 30,
    "x3_x4_limit": 40,
    "x1_x2_x3_min": 20,
    "x3_x4_diff_limit": 10,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ATTRACTIONS = pyo.Set(initialize=d["attractions"], ordered=True)

    def bounds_rule(m, i):
        return (0, d["upper_bound"][i])

    model.tours = pyo.Var(
        model.ATTRACTIONS,
        domain=pyo.NonNegativeIntegers,
        bounds=bounds_rule,
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.tours[i] for i in m.ATTRACTIONS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def c_x1_x2_rule(m):
        return m.tours[1] + m.tours[2] <= d["x1_x2_limit"]

    model.c_x1_x2 = pyo.Constraint(rule=c_x1_x2_rule)

    def c_x3_x4_rule(m):
        return 2 * m.tours[3] + m.tours[4] <= d["x3_x4_limit"]

    model.c_x3_x4 = pyo.Constraint(rule=c_x3_x4_rule)

    def c_demand_rule(m):
        return m.tours[1] + m.tours[2] + m.tours[3] >= d["x1_x2_x3_min"]

    model.c_demand = pyo.Constraint(rule=c_demand_rule)

    def c_diff_rule(m):
        # tours[3] - 0.5 * tours[4] <= 10  ->  2*tours[3] - tours[4] <= 20
        return 2 * m.tours[3] - m.tours[4] <= 2 * d["x3_x4_diff_limit"]

    model.c_diff = pyo.Constraint(rule=c_diff_rule)

    return model


